void stock(const std::filesystem::path& folder){AssetStore assets(folder);MissionAssetCache cache(assets);const auto definitions=build_runtime_items(cache.items());std::vector<AiItemDefinition> entries;for(const auto& d:definitions)entries.push_back({d.id,d.flags,d.model,d.ai_data,d.move_data,static_cast<std::uint16_t>(d.hp)});const auto bytes=assets.read("C05M07.BMS").bytes;const auto mission=decode_mission(bytes);AiActorFactory factory(AiItemDefinitionTable(entries),{});AiActorTables tables;for(std::size_t g=0;g<4;++g)for(std::size_t i=0;i<mission.object_groups[g].size();++i)tables.groups[g].push_back(factory.convert(mission.object_groups[g][i],actor_handle(g,i)));MissionTickState state;init_mission_tick(state,{},std::move(tables),AiItemDefinitionTable(entries),factory.people().slots(),1);std::ifstream file(folder/"Df.exe",std::ios::binary);AssetBytes executable((std::istreambuf_iterator<char>(file)),{});Fixed3 listener{};U yaw=0;MissionAudioFrameCells cells{0,listener,yaw};const TerrainGeometry* terrain=nullptr;MissionSoundRuntime sound(assets,executable,cells,terrain,{});const auto& raw=sound.asset_bindings();constexpr U D=0x18000000;auto current=mission_event_live_bindings(state,[&](U at,U width){if(at>=D&&std::uint64_t(at-D)+width<=definitions.size()*0x13c){check(width==4&&(at-D)%0x13c==0x20,"Current definition field");return definitions.at((at-D)/0x13c).id;}return raw.read(at,width);},raw.write,[&](std::size_t index){check(index<definitions.size(),"Current definition extent");return D+U(index)*0x13c;},[]{return std::uint16_t(0x037f);});MissionEventResourceBindings b;b.read=[&](U at,unsigned width){return current.read(at,width);};b.write=[&](U at,unsigned width,U value){current.write(at,width,value);};b.call=[&](U site,const std::vector<U>& args)->U{if(site==0x42eea0){mission_event_markers_triggers(b);return 0;}if(site==0x42f020){mission_event_markers_actions(b);return 0;}return raw.call(site,args);};MissionEventMemory memory(b);Host host;host.current=&current;EventStage stage(&host);stage.attach_source(memory);EventStage expected;expected.load(mission);const U name=raw.call(0x497f60,{32,16,0,0});const std::string filename="C05M07.BMS";for(U i=0;i<=filename.size();++i)raw.write(name+i,1,i<filename.size()?U(filename[i]):0);U objects=0;for(const auto& group:mission.object_groups)objects+=U(group.size());const U offset=268+objects*96+17408+2048+640;check(std::uint64_t(offset)+12+mission.events.size()*24+(mission.triggers.size()+mission.actions.size())*32==bytes.size(),"Actual BMS event extent");check(raw.call(0x499120,{name})!=0xffffffffu,"Actual BMS open");raw.call(0x4992d0,{offset,0});memory.load_current_file();raw.call(0x499020,{});
 for(U i=0;i<mission.triggers.size();++i)for(U w=0;w<8;++w)check(stage.trigger_view(i).read(w*4,4)==expected.trigger(i)[w],"Canonical actual marker trigger");for(U i=0;i<mission.actions.size();++i)for(U w=0;w<8;++w)check(stage.action_view(i).read(w*4,4)==expected.action(i)[w],"Canonical actual marker action");
 auto action=stage.action_view(0);U classification=0;for(const auto& actor:state.tables.groups[3])if(actor.person_slot&&(actor.field_70==1||actor.field_70==2)){classification=actor.field_70;break;}check(classification!=0,"Actual person class");action.write(4,4,classification==2?12:13);action.write(8,4,2);action.write(12,4,0x80000000);action.write(16,4,1);action.write(20,4,0x7fffffff);action.write(24,4,0x80000000);action.write(28,4,0x7fffffff);stage.dispatch_action_record(action.source_address());unsigned edited=0;for(const auto& actor:state.tables.groups[3])if(actor.person_slot&&actor.field_70==classification){check(state.people[*actor.person_slot].flags24&2,"Actual raw region/person shared write");++edited;}check(edited>0,"Actual region selection empty");
 U side=0;for(const auto& actor:state.tables.groups[3])if(actor.person_slot&&actor.field_72){side=actor.field_72;break;}check(side!=0,"Actual side");action.write(4,4,3);action.write(8,4,3);action.write(12,4,side);action.write(16,4,1);stage.dispatch_action_record(action.source_address());unsigned side_edits=0;for(const auto& group:state.tables.groups)for(const auto& actor:group)if(actor.person_slot&&actor.field_72==side){check(state.people[*actor.person_slot].flags24&0x10,"Actual raw side/person shared write");++side_edits;}check(side_edits>0,"Actual side selection empty");
 const U base=memory.table_base(EventTable::events);auto trigger=stage.trigger_view(0);trigger.write(4,4,2);trigger.write(12,4,74);check(stage.evaluate_trigger_record(trigger.source_address())==raw.read(base+74*24+20,1),"Actual fired-byte arena read");stage.set_flag_42ee50(5);check(current.read(0x67dbec,4)&32,"Current objective scalar");auto retained=stage.event_view(0);stage.reset();check(stage.event_count()==0&&retained.read(4,4)!=0,"Actual reset/retained arena");std::cout<<"Actual C05M07 shared marker/region/person/event/arena join passed\n";
}
